'use client'

import { useState, useEffect } from 'react';
import { useRouter } from 'next/router';
import en from '../../messages/en.json';
import hi from '../../messages/hi.json';

const AwarenessPage = () => {
  const [language, setLanguage] = useState('en');
  const [translations, setTranslations] = useState(en); // Default to English
  const { locale } = useRouter();

  useEffect(() => {
    // Switch between English and Hindi based on language selection
    if (locale === 'hi') {
      setLanguage('hi');
      setTranslations(hi);
    } else {
      setLanguage('en');
      setTranslations(en);
    }
  }, [locale]);

  return (
    <div className="awareness-container">
      <h1>{translations.title}</h1>
      <p>{translations.subtitle}</p>
      
      <div className="tabs">
        <button>{translations.tabs.addressing}</button>
        <button>{translations.tabs.services}</button>
        <button>{translations.tabs.guidelines}</button>
        <button>{translations.tabs.digipin}</button>
      </div>

      {/* Addressing Section */}
      <section>
        <h2>{translations.addressing.title}</h2>
        {translations.addressing.steps.map((step) => (
          <div key={step.number} className="address-step">
            <h3>{step.heading}</h3>
            <p>{step.description}</p>
          </div>
        ))}
        <div className="example-address">
          <h3>{translations.addressing.example.heading}</h3>
          <pre>
            {translations.addressing.example.address.join('\n')}
          </pre>
        </div>
        <div className="address-tips">
          <h3>{translations.addressing.tips.heading}</h3>
          <ul>
            {translations.addressing.tips.items.map((tip, index) => (
              <li key={index}>{tip}</li>
            ))}
          </ul>
        </div>
      </section>

      {/* Services Section */}
      <section>
        <h2>{translations.services[0].title}</h2>
        <p>{translations.services[0].description}</p>
        <ul>
          {translations.services[0].features.map((feature, index) => (
            <li key={index}>{feature}</li>
          ))}
        </ul>
      </section>

      {/* Packaging and Prohibited Items Section */}
      <section>
        <h2>{translations.guidelines.packaging.title}</h2>
        <ul>
          {translations.guidelines.packaging.items.map((item, index) => (
            <li key={index}>
              <strong>{item.heading}:</strong> {item.description}
            </li>
          ))}
        </ul>
        <h2>{translations.guidelines.prohibited.title}</h2>
        <ul>
          {translations.guidelines.prohibited.items.map((item, index) => (
            <li key={index}>{item}</li>
          ))}
        </ul>
      </section>

      {/* DigiPin Section */}
      <section>
        <h2>{translations.digipin.title}</h2>
        <h3>{translations.digipin.benefits.title}</h3>
        <ul>
          {translations.digipin.benefits.items.map((benefit, index) => (
            <li key={index}>{benefit}</li>
          ))}
        </ul>
        <h3>{translations.digipin.howToGet.title}</h3>
        <ol>
          {translations.digipin.howToGet.steps.map((step, index) => (
            <li key={index}>
              <strong>{step.heading}:</strong> {step.description}
            </li>
          ))}
        </ol>
      </section>
    </div>
  );
};

export default AwarenessPage;
